13	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
14	// stars move faster. Returns its own teardown. Ported from the approved
15	// prototype so the shipped page matches it exactly.
16	function startDrift(canvas: HTMLCanvasElement): () => void {
17	  const ctx = canvas.getContext("2d");
18	  if (ctx === null) return () => {};
19	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
20	  let w = 0;
21	  let h = 0;
22	  let raf = 0;
23	  let stars: Star[] = [];
24	
25	  function size() {
26	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
27	    w = canvas.clientWidth;
28	    h = canvas.clientHeight;
29	    canvas.width = w * dpr;
30	    canvas.height = h * dpr;
31	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
32	  }
33	
34	  function build() {
35	    size();
36	    const count = Math.min(300, Math.floor((w * h) / 3600));
37	    stars = [];
38	    for (let i = 0; i < count; i++) {
39	      const depth = Math.random();
40	      stars.push({
41	        x: Math.random() * w,
42	        y: Math.random() * h,
43	        size: 0.5 + depth * 1.6,
44	        base: 0.1 + depth * 0.45,
45	        sp: 0.05 + depth * 0.22,
46	        tw: Math.random() * 6.28,
47	        hot: Math.random() < 0.04,
48	      });
49	    }
50	  }
51	
52	  function frame(t: number) {
53	    const time = t / 1000;
54	    ctx!.clearRect(0, 0, w, h);
55	    for (const s of stars) {
56	      if (!reduce) {
57	        s.x += s.sp;
58	        if (s.x > w + 2) s.x = -2;
59	      }
60	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
61	      ctx!.beginPath();
