93	// The drifting star field as a self-contained background layer. Runs for the
94	// host's lifetime and tears down its animation frame on unmount; a single still
95	// frame under reduced motion. Shared by the waitlist and the sign-in landing so
96	// both ride the exact same sky.
97	export function DriftSky({ className }: { className?: string }) {
98	  const canvasRef = useRef<HTMLCanvasElement>(null);
99	  useEffect(() => {
100	    const canvas = canvasRef.current;
101	    if (canvas === null) return;
102	    return startDrift(canvas);
103	  }, []);
104	  return <canvas ref={canvasRef} className={className} aria-hidden="true" />;
105	}
